mapper.insert:

INSERT INTO G_LOCGOV_IMAGE
	(
		LOCGOV_CODE
		, PC_FILE_NAME
		, MOBILE_FILE_NAME
		, FRST_REGISTER_ID
		, FRST_REGIST_PNTTM
		, LAST_UPDUSR_ID
		, LAST_UPDT_PNTTM
	)
	VALUES
	(
		#{locgovCode}
		, #{pcFileName}
		, #{mobileFileName}
		, #{frstRegisterId}
		, #{frstRegistPnttm}
		, #{lastUpdusrId}
		, #{lastUpdtPnttm}
	)

mapper.update:

UPDATE G_LOCGOV_IMAGE
	SET 
		LAST_UPDUSR_ID = #{lastUpdusrId}
		, LAST_UPDT_PNTTM = #{lastUpdtPnttm}

		, PC_FILE_NAME = #{pcFileName}


		, MOBILE_FILE_NAME = #{mobileFileName}

	WHERE LOCGOV_CODE = #{locgovCode}
